466	    private ResultActions diffArrive(String legId, int expectedVersion, List<String> bagTags) throws Exception {
467	        return postJson("/api/legs/" + legId + "/arrive-difference", Map.of(
468	                "requestId", UUID.randomUUID().toString(),
469	                "expectedVersion", expectedVersion, "bagTags", bagTags));
470	    }
